package com.ci.pipeline.auth

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

enum class Role(val level: Int) {
    VIEWER(0),
    DEVELOPER(1),
    MAINTAINER(2),
    ADMIN(3)
}

data class User(val id: String, val username: String, val role: Role)
data class Pipeline(val id: String, val ownerId: String, val requiredRole: Role)
data class ActionRequest(val userId: String, val pipelineId: String, val action: String, val signature: String)

class PipelineAccessController(hmacSecret: ByteArray) {
    private val users = ConcurrentHashMap<String, User>()
    private val pipelines = ConcurrentHashMap<String, Pipeline>()
    private val delegations = ConcurrentHashMap<String, MutableSet<String>>()
    private val hmacSecret: ByteArray = hmacSecret.copyOf()

    fun registerUser(id: String, username: String, role: Role) {
        users[id] = User(id, username, role)
    }

    fun createPipeline(id: String, ownerId: String, requiredRole: Role) {
        pipelines[id] = Pipeline(id, ownerId, requiredRole)
    }

    fun delegateAccess(fromUserId: String, toUserId: String): Boolean {
        val fromUser = users[fromUserId] ?: return false
        val toUser = users[toUserId] ?: return false
        if (fromUser.role.level <= toUser.role.level) return false
        delegations.getOrPut(toUserId) { mutableSetOf() }.add(fromUserId)
        return true
    }

    fun computeEffectiveRole(userId: String): Role {
        val user = users[userId] ?: return Role.VIEWER
        val delegatedFrom = delegations[userId] ?: return user.role

        var maxLevel = user.role.level
        val visited = mutableSetOf<String>()
        val queue = ArrayDeque<String>()
        queue.addAll(delegatedFrom)

        while (queue.isNotEmpty()) {
            val currentId = queue.removeFirst()
            if (currentId in visited) continue
            visited.add(currentId)

            val current = users[currentId] ?: continue
            if (current.role.level > maxLevel) {
                maxLevel = current.role.level
            }

            // Do NOT traverse transitive delegations - only direct grants
        }

        return Role.values().first { it.level == maxLevel }
    }

    fun verifySignature(request: ActionRequest): Boolean {
        val payload = "${request.userId}:${request.pipelineId}:${request.action}"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacSecret, "HmacSHA256"))
        val expected = mac.doFinal(payload.toByteArray()).toHexString()
        return timingSafeEquals(expected, request.signature)
    }

    private fun timingSafeEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].code xor b[i].code)
        }
        return result == 0
    }

    fun checkAccess(userId: String, pipelineId: String): Boolean {
        val pipeline = pipelines[pipelineId] ?: return false
        val effectiveRole = computeEffectiveRole(userId)
        return effectiveRole.level >= pipeline.requiredRole.level
    }

    fun executeAction(request: ActionRequest): Result<String> {
        if (!verifySignature(request)) {
            return Result.failure(SecurityException("Invalid signature"))
        }

        if (!checkAccess(request.userId, request.pipelineId)) {
            return Result.failure(SecurityException("Insufficient permissions"))
        }

        return Result.success("Action '${request.action}' executed on pipeline '${request.pipelineId}'")
    }

    fun revokeUser(adminId: String, targetId: String): Boolean {
        val admin = users[adminId] ?: return false
        if (admin.role != Role.ADMIN) return false

        users.remove(targetId)
        delegations.remove(targetId)
        // Also clean up references in other delegation sets
        delegations.values.forEach { it.remove(targetId) }
        return true
    }
}

private fun ByteArray.toHexString(): String = joinToString("") { "%02x".format(it) }

fun main() {
    // HMAC secret must be supplied externally (e.g., environment variable / secure config),
    // never hard-coded in source.
    val secret = System.getenv("PIPELINE_HMAC_SECRET")
        ?: error("PIPELINE_HMAC_SECRET environment variable must be set")
    val controller = PipelineAccessController(secret.toByteArray())

    controller.registerUser("u1", "alice", Role.ADMIN)
    controller.registerUser("u2", "bob", Role.DEVELOPER)
    controller.registerUser("u3", "charlie", Role.VIEWER)

    controller.createPipeline("p1", "u1", Role.ADMIN)

    // Admin delegates to developer
    controller.delegateAccess("u1", "u2")
    // Developer delegates to viewer (should fail - dev not higher than dev)
    controller.delegateAccess("u2", "u3")

    println("Bob effective role: ${controller.computeEffectiveRole("u2")}")
    println("Charlie effective role: ${controller.computeEffectiveRole("u3")}")
    println("Bob can access p1: ${controller.checkAccess("u2", "p1")}")
}
